  Lemma rrenv_transport_img : forall tp TSD CTX TH sb ARI m m' W,
    AS_Refill1.RENV tp TSD CTX TH sb ARI m -> munch W m m' -> wmono bsegs m m' -> out_img W ->
    65536 <= bv_unsigned tp + -88 -> bv_unsigned tp + -88 + 8 <= 6832128 ->
